import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        ERockPaperScissors solver = new ERockPaperScissors();
        solver.solve(1, br, pw);
        pw.close();
    }

    static class ERockPaperScissors {
        int min;

        public void check(List<int[]> pairs, int[] a, int[] b) {
            for (int[] pair : pairs) {
                int m = Math.min(a[pair[0]], b[pair[1]]);
                b[pair[1]] -= m;
                a[pair[0]] -= m;
            }
            int remaining = 0;
            for (int i = 0; i < 3; i++) remaining += a[i];
            min = Math.min(min, remaining);
        }

        public void permute(List<int[]> pairs, int index, int[] a, int[] b) {
            check(pairs, a.clone(), b.clone());
            for (int i = index; i < pairs.size(); i++) {
                Collections.swap(pairs, i, index);
                permute(pairs, index + 1, a, b);
                Collections.swap(pairs, i, index);
            }
        }

        public void solve(int testNumber, BufferedReader br, PrintWriter pw) throws IOException {
            int n = Integer.parseInt(br.readLine());
            int[] a = new int[3];
            int[] b = new int[3];
            min = Integer.MAX_VALUE;
            String[] parts = br.readLine().split(" ");
            for (int i = 0; i < 3; i++) a[i] = Integer.parseInt(parts[i]);
            parts = br.readLine().split(" ");
            for (int i = 0; i < 3; i++) b[i] = Integer.parseInt(parts[i]);
            int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            List<int[]> pairs = new ArrayList<>();
            pairs.add(new int[]{0, 0});
            pairs.add(new int[]{1, 1});
            pairs.add(new int[]{2, 2});
            pairs.add(new int[]{0, 2});
            pairs.add(new int[]{1, 0});
            pairs.add(new int[]{2, 1});
            permute(pairs, 0, a, b);
            pw.println(min + " " + max);
        }
    }
}
